// G1 validation: prepare snapshots for s1/s2, run diff_contracts, compare
// against ground_truth.yaml. Run with:
//   cd packages/api && ./node_modules/.bin/tsx scripts/validate-s1s2.ts
// Requires a running lain server (LAIN_TOOL_PROFILE=contracts) on :9999
// against the fixture generated by scripts/contracts-fixture.sh.

import { createLainClient } from '../src/lain-adapter/client.js';
import type {
  PrepareSnapshotResponse,
  GetSnapshotResponse,
  DiffContractsResponse,
} from '@parallax/shared/lain';

const LAIN_URL = process.env.LAIN_URL ?? 'http://localhost:9999/mcp';

// Fixture SHAs from contracts-fixture.sh (deterministic).
const SHAS = {
  ordersBase: 'b5bf29ad1d5d6b84ef9655ee7a035a4a5c8523cf',
  ordersS1: 'afece2321df86647a31d073a2e3cadb50e13d42e',
  ordersS2: '0931d02684c2d1f6df7f0353f6e6bdd6c07ecc2c',
  billingBase: '972651746b73f234031e3eae3c7b71b5d255d0ef',
  reportsBase: '06f27bd72248a3c8513bc58807d98de15c286b8c',
  platformBase: 'efec0ee36e7b76d47d1810c14cd3574c3c75292c',
};

function ok(msg: string) {
  console.log(`  ✓ ${msg}`);
}
function fail(msg: string) {
  console.log(`  ✗ ${msg}`);
  process.exitCode = 1;
}

async function prepareAndWait(
  adapter: Awaited<ReturnType<typeof createLainClient>>,
  repos: Record<string, string>,
  label: string,
): Promise<string> {
  const prep = (await adapter.prepareSnapshot({ repos })) as PrepareSnapshotResponse;
  ok(`${label}: prepare_snapshot → ${prep.snapshot} (${prep.state})`);
  if (prep.state === 'ready') {
    ok(`${label}: snapshot ready immediately`);
    return prep.snapshot;
  }
  for (let i = 0; i < 30; i++) {
    await new Promise((r) => setTimeout(r, 200));
    const snap = (await adapter.getSnapshot({
      snapshot: prep.snapshot,
    })) as GetSnapshotResponse;
    if (snap.state === 'ready') {
      ok(`${label}: snapshot ready`);
      return prep.snapshot;
    }
    if (snap.state === 'failed') {
      fail(`${label}: snapshot failed: ${snap.error}`);
      throw new Error('snapshot failed');
    }
  }
  fail(`${label}: snapshot did not become ready in 6s`);
  throw new Error('timeout');
}

async function main() {
  console.log(`Validating s1/s2 against lain at ${LAIN_URL}`);
  const adapter = await createLainClient({ lainUrl: LAIN_URL, apiVersion: '1' });
  ok(`handshake OK (analyzerVersion=${adapter.analyzerVersion})`);

  // --- s1: orders base → s1-remove-customer-id, billing stays base ---
  console.log('\n=== s1-remove-customer-id ===');
  const baseRepos = {
    orders: SHAS.ordersBase,
    billing: SHAS.billingBase,
    reports: SHAS.reportsBase,
    platform: SHAS.platformBase,
  };
  const s1HeadRepos = {
    orders: SHAS.ordersS1,
    billing: SHAS.billingBase,
    reports: SHAS.reportsBase,
    platform: SHAS.platformBase,
  };
  const s1BaseId = await prepareAndWait(adapter, baseRepos, 's1 base');
  const s1HeadId = await prepareAndWait(adapter, s1HeadRepos, 's1 head');
  const s1Diff = (await adapter.diffContracts({
    base: s1BaseId,
    head: s1HeadId,
  })) as DiffContractsResponse;
  ok(`s1: diff_contracts → ${s1Diff.changes.length} changes`);

  const s1FieldRemoved = s1Diff.changes.find(
    (c) => c.kind === 'FieldRemoved' && c.field === 'customer_id',
  );
  if (s1FieldRemoved) {
    ok(`s1: FieldRemoved of customer_id on ${s1FieldRemoved.endpoint?.service ?? 'unknown'}`);
  } else {
    fail(`s1: expected FieldRemoved of customer_id, got ${JSON.stringify(s1Diff.changes)}`);
  }

  const s1BillingAffected = s1Diff.changes.find(
    (c) => c.kind === 'FieldRemoved' && c.field === 'customer_id',
  );
  if (s1BillingAffected) {
    ok(`s1: change is on ${s1BillingAffected.endpoint?.service} (expected orders)`);
    if (s1BillingAffected.endpoint?.service === 'orders') {
      ok('s1: change is on the provider (orders)');
    } else {
      fail(`s1: change is on ${s1BillingAffected.endpoint?.service}, expected orders`);
    }
  }

  // --- s2: orders base → s2-add-currency (compatible, no FieldRemoved) ---
  console.log('\n=== s2-add-currency ===');
  const s2HeadRepos = {
    orders: SHAS.ordersS2,
    billing: SHAS.billingBase,
    reports: SHAS.reportsBase,
    platform: SHAS.platformBase,
  };
  const s2BaseId = await prepareAndWait(adapter, baseRepos, 's2 base');
  const s2HeadId = await prepareAndWait(adapter, s2HeadRepos, 's2 head');
  const s2Diff = (await adapter.diffContracts({
    base: s2BaseId,
    head: s2HeadId,
  })) as DiffContractsResponse;
  ok(`s2: diff_contracts → ${s2Diff.changes.length} changes (truncated=${s2Diff.truncated})`);

  const s2FieldRemoved = s2Diff.changes.filter((c) => c.kind === 'FieldRemoved');
  if (s2FieldRemoved.length === 0) {
    ok('s2: no FieldRemoved (compatible change, as expected)');
  } else {
    fail(`s2: unexpected FieldRemoved: ${JSON.stringify(s2FieldRemoved)}`);
  }

  if (s2Diff.changes.length === 0) {
    ok('s2: changes[] is empty (compatible field add not reported per §9.4)');
  } else {
    fail(`s2: expected empty changes[], got ${s2Diff.changes.length}`);
  }

  console.log('\n=== VALIDATION RESULT ===');
  if (process.exitCode !== 1) {
    console.log('s1/s2 ground truth: PASS');
  } else {
    console.log('s1/s2 ground truth: FAIL');
  }
}

main().catch((e) => {
  console.error('FAIL:', e);
  process.exit(1);
});
